import{_ as a}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as t,o as i,c as o,al as r}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"Land Mode (Fixed-Wing)","description":"","frontmatter":{},"headers":[],"relativePath":"ko/flight_modes_fw/land.md","filePath":"ko/flight_modes_fw/land.md"}'),l={name:"ko/flight_modes_fw/land.md"};function d(n,e,s,h,c,_){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="land-mode-fixed-wing" tabindex="-1">Land Mode (Fixed-Wing) <a class="header-anchor" href="#land-mode-fixed-wing" aria-label="Permalink to &quot;Land Mode (Fixed-Wing)&quot;">​</a></h1><img src="'+a+'" title="Position estimate required (e.g. GPS)" width="30px"><p>The <em>Land</em> flight mode causes the vehicle to descend at the position where the mode was engaged, following a circular path until touchdown. After landing, vehicles will disarm after a short timeout (by default).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Fixed-wing <em>land mode</em> should only be used in an <strong>emergency</strong>! The vehicle will descend around the current location irrespective of the suitability of the underlying terrain, and touch down while following a circular flight path.</p><p>Where possible, instead use <a href="./../flight_modes_fw/return">Return mode</a> with a predefined <a href="./../flight_modes_fw/mission#mission-landing">Fixed-wing mission landing</a>.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li>Mode is automatic - no user intervention is <em>required</em> to control the vehicle.</li><li>Mode requires at least a valid local position estimate (does not require a global position). <ul><li>Flying vehicles can&#39;t switch to this mode without valid local position.</li><li>Flying vehicles will failsafe if they lose the position estimate.</li></ul></li><li>Mode prevents arming (vehicle cannot be armed while this mode is selected).</li><li>RC 제어 스위치는 기체의 비행 모드를 변경할 수 있습니다.</li><li>RC stick movement is ignored.</li><li>The mode can be triggered using the <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LAND" target="_blank" rel="noreferrer">MAV_CMD_NAV_LAND</a> MAVLink command, or by explicitly switching to Land mode.</li></ul></div><h2 id="technical-summary" tabindex="-1">Technical Summary <a class="header-anchor" href="#technical-summary" aria-label="Permalink to &quot;Technical Summary&quot;">​</a></h2><p>Land mode causes the vehicle follow a descending circular path (corkscrew) until touchdown.</p><p>When the mode is engaged, the vehicle starts to loiter around the current vehicle position with loiter radius <a href="#NAV_LOITER_RAD">NAV_LOITER_RAD</a> and begins to descend with a constant descent speed. The descent speed is calculated using <a href="#FW_LND_ANG">FW_LND_ANG</a> and the set landing airspeed <a href="#FW_LND_AIRSPD">FW_LND_AIRSPD</a>. The vehicle will flare if configured to do so (see <a href="./../flight_modes_fw/mission#flaring-roll-out">Flaring</a>), and otherwise proceed circling with the constant descent rate until landing is detected.</p><p><a href="./../flight_modes_fw/mission#automatic-abort">Manual nudging</a> and <a href="./../flight_modes_fw/mission#nudging">automatic land abort</a> are not available in land mode.</p><h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_alt"><code>mode_req_local_alt</code></a> — Local altitude relative to EKF2 origin (&#39;0&#39;) position</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_position_relaxed"><code>mode_req_local_position_relaxed</code></a> — Position relative to EKF2 origin (&#39;0&#39;) point but accepts poor accuracy</li><li><a href="./../flight_modes/mode_requirements#mode_req_prevent_arming"><code>mode_req_prevent_arming</code></a> — Mode prevents arming</li></ul><h3 id="매개변수" tabindex="-1">매개변수 <a class="header-anchor" href="#매개변수" aria-label="Permalink to &quot;매개변수&quot;">​</a></h3><p>Land mode behaviour can be configured using the parameters below.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>설명</th></tr></thead><tbody><tr><td><a id="NAV_LOITER_RAD"></a><a href="./../advanced_config/parameter_reference#NAV_LOITER_RAD">NAV_LOITER_RAD</a></td><td>The loiter radius that the controller tracks for the whole landing sequence.</td></tr><tr><td><a id="FW_LND_ANG"></a><a href="./../advanced_config/parameter_reference#FW_LND_ANG">FW_LND_ANG</a></td><td>The flight path angle setpoint.</td></tr><tr><td><a id="FW_LND_AIRSPD"></a><a href="./../advanced_config/parameter_reference#FW_LND_AIRSPD">FW_LND_AIRSPD</a></td><td>The airspeed setpoint.</td></tr><tr><td><a id="FW_AIRSPD_FLP_SC"></a><a href="./../advanced_config/parameter_reference#FW_AIRSPD_FLP_SC">FW_AIRSPD_FLP_SC</a></td><td>Factor applied to the minimum airspeed when flaps are fully deployed. Necessary if FW_LND_AIRSPD is below FW_AIRSPD_MIN.</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../flight_modes_mc/land">Land Mode (MC)</a></li><li><a href="./../flight_modes_vtol/land">Land Mode (VTOL)</a></li></ul>',17)])])}const g=t(l,[["render",d]]);export{f as __pageData,g as default};
